/// Database Queries for Interestnaut
/// 
/// This file contains all SQL queries used by the SQLite database.
/// The database uses a normalized schema with these main tables:
/// - media_items: Central table for all media content
/// - recommendations: Suggestions generated by the system
/// - favorites: User's favorite items (both recommended and user-added)
/// - watchlist: User's watchlist items (both recommended and user-added)
/// - media_metadata: Flexible key-value storage for media properties
/// - user_constraints: User-defined search constraints

/// Static Data Tables

// Create media types table with predefined values
const String createMediaTypesTableQuery = '''
CREATE TABLE IF NOT EXISTS media_types (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT UNIQUE NOT NULL
);
''';

const String insertMediaTypesQuery = '''
  INSERT OR IGNORE INTO media_types (name) VALUES 
    ('music'), ('movie'), ('tv_show'), ('video_game'), ('book');
''';

// Create recommendation status table with predefined values
const String createRecommendationStatusTableQuery = '''
CREATE TABLE IF NOT EXISTS recommendation_status (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT UNIQUE NOT NULL
);
''';

const String insertRecommendationStatusQuery = '''
  INSERT OR IGNORE INTO recommendation_status (name) VALUES 
    ('pending'), ('liked'), ('disliked'), ('skipped'), ('added'), ('watchlist');
''';

/// Core Tables

// Create media items table (central table for all media content)
const String createMediaItemsTableQuery = '''
CREATE TABLE IF NOT EXISTS media_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  media_type_id INTEGER NOT NULL,
  vector_media_id TEXT NOT NULL,
  title TEXT NOT NULL,
  primary_creator TEXT,
  cover_art_url TEXT,
  description TEXT,
  wiki_url TEXT,
  wikidata_id TEXT,
  themes TEXT,
  genres TEXT,
  youtube_id TEXT,
  spotify_id TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (media_type_id) REFERENCES media_types (id),
  UNIQUE(media_type_id, title, primary_creator)
);

CREATE INDEX IF NOT EXISTS idx_media_items_type ON media_items(media_type_id);
CREATE INDEX IF NOT EXISTS idx_media_items_title ON media_items(title);
CREATE INDEX IF NOT EXISTS idx_media_items_creator ON media_items(primary_creator);
CREATE INDEX IF NOT EXISTS idx_media_items_vector_id ON media_items(vector_media_id);
''';

// Create recommendations table
const String createRecommendationsTableQuery = '''
CREATE TABLE IF NOT EXISTS recommendations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  media_item_id INTEGER NOT NULL,
  query TEXT NOT NULL,
  bot_reasoning TEXT,
  status_id INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT,
  FOREIGN KEY (media_item_id) REFERENCES media_items (id),
  FOREIGN KEY (status_id) REFERENCES recommendation_status (id),
  UNIQUE(media_item_id)
);

CREATE INDEX IF NOT EXISTS idx_recommendations_media_item ON recommendations(media_item_id);
CREATE INDEX IF NOT EXISTS idx_recommendations_status ON recommendations(status_id);
''';

// Create favorites table (simplified - no recommendation_id needed)
const String createFavoritesTableQuery = '''
CREATE TABLE IF NOT EXISTS favorites (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  media_item_id INTEGER NOT NULL,
  created_at TEXT NOT NULL,
  FOREIGN KEY (media_item_id) REFERENCES media_items (id),
  UNIQUE(media_item_id)
);

CREATE INDEX IF NOT EXISTS idx_favorites_media_item ON favorites(media_item_id);
''';

// Create watchlist table (simplified - no recommendation_id needed)
const String createWatchlistTableQuery = '''
CREATE TABLE IF NOT EXISTS watchlist (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  media_item_id INTEGER NOT NULL,
  created_at TEXT NOT NULL,
  FOREIGN KEY (media_item_id) REFERENCES media_items (id),
  UNIQUE(media_item_id)
);

CREATE INDEX IF NOT EXISTS idx_watchlist_media_item ON watchlist(media_item_id);
''';

// Create media metadata table for flexible key-value storage
const String createMediaMetadataTableQuery = '''
CREATE TABLE IF NOT EXISTS media_metadata (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  media_item_id INTEGER NOT NULL,
  key TEXT NOT NULL,
  value TEXT NOT NULL,
  FOREIGN KEY (media_item_id) REFERENCES media_items (id),
  UNIQUE(media_item_id, key)
);

CREATE INDEX IF NOT EXISTS idx_media_metadata_key ON media_metadata(key);
''';

// Create media blends table
const String createMediaBlendsTableQuery = '''
CREATE TABLE IF NOT EXISTS media_blends (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  primary_media_type_id INTEGER NOT NULL,
  blended_media_type_id INTEGER NOT NULL,
  created_at TEXT NOT NULL,
  FOREIGN KEY (primary_media_type_id) REFERENCES media_types (id),
  FOREIGN KEY (blended_media_type_id) REFERENCES media_types (id),
  UNIQUE(primary_media_type_id, blended_media_type_id)
);

CREATE INDEX IF NOT EXISTS idx_media_blends_primary ON media_blends(primary_media_type_id);
''';

// Create media matching table
const String createMediaMatchingTableQuery = '''
CREATE TABLE IF NOT EXISTS media_matching (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  media_type_id INTEGER NOT NULL,
  value TEXT NOT NULL,
  is_positive BOOLEAN NOT NULL,
  created_at TEXT NOT NULL,
  FOREIGN KEY (media_type_id) REFERENCES media_types (id),
  UNIQUE(media_type_id, value)
);

CREATE INDEX IF NOT EXISTS idx_media_matching_type ON media_matching(media_type_id);
''';

// Create media priority titles table
const String createMediaPriorityTitlesTableQuery = '''
CREATE TABLE IF NOT EXISTS media_priority_titles (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  media_type_id INTEGER NOT NULL,
  media_item_id INTEGER NOT NULL,
  is_positive BOOLEAN NOT NULL,
  created_at TEXT NOT NULL,
  FOREIGN KEY (media_type_id) REFERENCES media_types (id),
  FOREIGN KEY (media_item_id) REFERENCES media_items (id),
  UNIQUE(media_type_id, media_item_id)
);

CREATE INDEX IF NOT EXISTS idx_media_priority_titles_type ON media_priority_titles(media_type_id);
''';

// Create media settings table
const String createMediaSettingsTableQuery = '''
CREATE TABLE IF NOT EXISTS media_settings (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  media_type_id INTEGER NOT NULL,
  similarity_matching REAL NOT NULL DEFAULT 0.5,
  themes_matching INTEGER NOT NULL DEFAULT 3,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (media_type_id) REFERENCES media_types (id),
  UNIQUE(media_type_id)
);

CREATE INDEX IF NOT EXISTS idx_media_settings_type ON media_settings(media_type_id);
''';

// Create general settings table for app-wide and media-specific settings
const String createGeneralSettingsTableQuery = '''
CREATE TABLE IF NOT EXISTS general_settings (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  key TEXT NOT NULL UNIQUE,
  value TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_general_settings_key ON general_settings(key);
''';

