// Get watchlist items (legacy compatibility - simplified without negative IDs)
const String getWatchlistItemsQuery = '''
SELECT 
  COALESCE(r.id, mi.id) as id, -- Use recommendation ID if exists, otherwise media_item_id
  mi.id as media_item_id, 
  COALESCE(r.query, 'User Added') as query, 
  COALESCE(r.bot_reasoning, 'Added from search') as bot_reasoning,
  mi.vector_media_id, mi.title, mi.primary_creator, mi.cover_art_url,
  mi.description, mi.wiki_url, mi.wikidata_id, mi.themes, mi.genres,
  mt.name as media_type, 
  COALESCE(rs.name, 'added') as status,
  COALESCE(r.created_at, w.created_at) as created_at, 
  COALESCE(r.updated_at, w.created_at) as updated_at, 
  w.created_at as watchlist_added_at
FROM watchlist w
JOIN media_items mi ON w.media_item_id = mi.id
JOIN media_types mt ON mi.media_type_id = mt.id
LEFT JOIN recommendations r ON mi.id = r.media_item_id AND r.id = (
  SELECT MAX(r2.id) FROM recommendations r2 WHERE r2.media_item_id = mi.id
)
LEFT JOIN recommendation_status rs ON r.status_id = rs.id
WHERE mt.name = ?
GROUP BY mi.id
ORDER BY w.created_at DESC;
''';

// Get favorites items (legacy compatibility)
const String getFavoritesItemsQuery = '''
SELECT 
  COALESCE(r.id, mi.id) as id, -- Use recommendation ID if exists, otherwise media_item_id
  mi.id as media_item_id, 
  COALESCE(r.query, 'User Added') as query, 
  COALESCE(r.bot_reasoning, 'Added from search') as bot_reasoning,
  mi.vector_media_id, mi.title, mi.primary_creator, mi.cover_art_url,
  mi.description, mi.wiki_url, mi.wikidata_id, mi.themes, mi.genres,
  mt.name as media_type, 
  COALESCE(rs.name, 'added') as status,
  COALESCE(r.created_at, f.created_at) as created_at, 
  COALESCE(r.updated_at, f.created_at) as updated_at, 
  f.created_at as favorited_at
FROM favorites f
JOIN media_items mi ON f.media_item_id = mi.id
JOIN media_types mt ON mi.media_type_id = mt.id
LEFT JOIN recommendations r ON mi.id = r.media_item_id
LEFT JOIN recommendation_status rs ON r.status_id = rs.id
WHERE mt.name = ?
ORDER BY f.created_at DESC;
''';